20	/**
21	 * Security configuration using the deprecated WebSecurityConfigurerAdapter.
22	 * This needs to be migrated to component-based security configuration in Spring Security 6.
23	 */
24	@Configuration
25	@EnableWebSecurity
26	@EnableGlobalMethodSecurity(prePostEnabled = true)
27	public class SecurityConfig extends WebSecurityConfigurerAdapter {
28	
29	    @Autowired
30	    private UserDetailsService userDetailsService;
31	
32	    @Bean
33	    public PasswordEncoder passwordEncoder() {
34	        return new BCryptPasswordEncoder();
35	    }
36	
37	    @Override
38	    protected void configure(AuthenticationManagerBuilder auth) throws Exception {
39	        auth.userDetailsService(userDetailsService)
40	            .passwordEncoder(passwordEncoder());
41	    }
42	
43	    @Override
44	    @Bean
45	    public AuthenticationManager authenticationManagerBean() throws Exception {
46	        return super.authenticationManagerBean();
47	    }
48	
49	    @Override
50	    protected void configure(HttpSecurity http) throws Exception {
51	        http
52	            .csrf().disable()
53	            .sessionManagement()
54	                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
55	            .and()
56	            .exceptionHandling()
57	                .authenticationEntryPoint((request, response, ex) -> {
58	                    response.sendError(HttpServletResponse.SC_UNAUTHORIZED, ex.getMessage());
59	                })
60	            .and()
61	            .authorizeRequests()
62	                // Public endpoints
63	                .antMatchers(HttpMethod.POST, "/api/users").permitAll()
64	                .antMatchers("/api/auth/**").permitAll()
65	                .antMatchers("/h2-console/**").permitAll()
66	                .antMatchers("/actuator/health").permitAll()
67	                // All other endpoints require authentication
68	                .anyRequest().authenticated()
69	            .and()
70	            .headers().frameOptions().disable(); // For H2 console
71	    }
