15	/**
16	 * Service for making external API calls using RestTemplate.
17	 * This is a legacy pattern that should be migrated to RestClient in Spring Boot 3.
18	 */
19	@Service
20	public class ExternalApiService {
21	
22	    private final RestTemplate restTemplate;
23	
24	    @Value("${external.api.base-url:https://api.example.com}")
25	    private String baseUrl;
26	
27	    public ExternalApiService() {
28	        this.restTemplate = new RestTemplate();
29	    }
30	
31	    /**
32	     * Verify user email through external service
33	     */
34	    public boolean verifyEmail(String email) {
35	        try {
36	            String url = baseUrl + "/verify/email?email=" + email;
37	            ResponseEntity<Map> response = restTemplate.getForEntity(url, Map.class);
38	            if (response.getBody() != null) {
39	                Object valid = response.getBody().get("valid");
40	                return Boolean.TRUE.equals(valid);
41	            }
42	            return false;
43	        } catch (Exception e) {
44	            // Log and return false on failure
45	            return false;
46	        }
47	    }
48	
49	    /**
50	     * Send notification to external notification service
51	     */
52	    public void sendNotification(String userId, String message) {
53	        try {
54	            String url = baseUrl + "/notifications";
55	
56	            HttpHeaders headers = new HttpHeaders();
57	            headers.setContentType(MediaType.APPLICATION_JSON);
58	            headers.setAccept(Collections.singletonList(MediaType.APPLICATION_JSON));
59	
60	            Map<String, String> payload = Map.of(
61	                "userId", userId,
62	                "message", message,
63	                "type", "USER_UPDATE"
64	            );
65	
66	            HttpEntity<Map<String, String>> request = new HttpEntity<>(payload, headers);
67	            restTemplate.postForEntity(url, request, Void.class);
68	        } catch (Exception e) {
69	            // Log notification failure but don't throw
70	            System.err.println("Failed to send notification: " + e.getMessage());
71	        }
72	    }
73	
74	    /**
75	     * Fetch user profile enrichment data from external service
76	     */
77	    public Map<String, Object> enrichUserProfile(String userId) {
78	        try {
79	            String url = baseUrl + "/users/" + userId + "/profile";
80	
81	            HttpHeaders headers = new HttpHeaders();
82	            headers.setAccept(Collections.singletonList(MediaType.APPLICATION_JSON));
83	
84	            HttpEntity<?> request = new HttpEntity<>(headers);
85	
86	            ResponseEntity<Map> response = restTemplate.exchange(
87	                url,
88	                HttpMethod.GET,
89	                request,
90	                Map.class
91	            );
92	
93	            return response.getBody() != null ? response.getBody() : Collections.emptyMap();
94	        } catch (Exception e) {
95	            return Collections.emptyMap();
96	        }
97	    }
98	
